# Let's find a Golomb ruler with 6 marks using brute force or known construction
# First mark at 0, increasing order.

def is_golomb(marks):
    n = len(marks)
    distances = set()
    for i in range(n):
        for j in range(i+1, n):
            d = marks[j] - marks[i]
            if d in distances:
                return False
            distances.add(d)
    return True

# Let's try to find one with small max mark
# We'll search with backtracking

def find_golomb(n, max_length):
    marks = [0]

    def backtrack():
        if len(marks) == n:
            return list(marks)

        # Try next mark
        start = marks[-1] + 1
        for next_mark in range(start, max_length + 1):
            # Check if all new distances are unique
            ok = True
            new_dists = set()
            for m in marks:
                d = next_mark - m
                if d in new_dists:  # shouldn't happen since marks are distinct
                    ok = False
                    break
                new_dists.add(d)

            if not ok:
                continue

            # Check against all existing distances
            existing_dists = set()
            for i in range(len(marks)):
                for j in range(i+1, len(marks)):
                    existing_dists.add(marks[j] - marks[i])

            conflict = False
            for d in new_dists:
                if d in existing_dists:
                    conflict = True
                    break

            if conflict:
                continue

            marks.append(next_mark)
            result = backtrack()
            if result is not None:
                return result
            marks.pop()

        return None

    return backtrack()

# Search for n=6
for max_len in range(10, 30):
    result = find_golomb(6, max_len)
    if result:
        print(f"Found with max_length {max_len}: {result}")
        break
